<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Roles {
    public static function manageDefinition(\PDO $p,int $actor,array $d): int {
        Authorization::require($p,$actor,'core.roles.manage');$module=Core::text($d['module_code']??'',64);Core::module($p,$module,false);$code=Core::text($d['code']??'',64);if(!preg_match('/\A[a-z0-9_.-]+\z/',$code)||in_array($code,['super_admin','pkd_admin','clinic_admin','unit_admin','staff'],true))throw new \InvalidArgumentException('Kod role dilindungi atau tidak sah.');$name=Core::text($d['name']??'',100);$permissions=$d['permissions']??[];if(!is_array($permissions)||count($permissions)>200)throw new \InvalidArgumentException('Permission tidak sah.');
        return Core::tx($p,function()use($p,$actor,$module,$code,$name,$permissions){$r=Database::query($p,'SELECT * FROM roles WHERE code=? FOR UPDATE',[$code])->fetch();$before=$r?[...$r,'permissions'=>Database::query($p,'SELECT permission_id FROM role_permissions WHERE role_id=?',[$r['id']])->fetchAll(\PDO::FETCH_COLUMN)]:null;if($r&&($r['is_system']||$r['module_code']!==$module))throw new \InvalidArgumentException('Role dilindungi.');if(!$r){Database::query($p,'INSERT INTO roles(code,name,module_code) VALUES(?,?,?)',[$code,$name,$module]);$id=(int)$p->lastInsertId();}else{$id=(int)$r['id'];Database::query($p,'UPDATE roles SET name=? WHERE id=?',[$name,$id]);Database::query($p,'DELETE FROM role_permissions WHERE role_id=?',[$id]);}foreach($permissions as $pid){$pid=Core::id($pid);if(!Database::query($p,'SELECT 1 FROM permissions WHERE id=? AND module_code=?',[$pid,$module])->fetchColumn())throw new \InvalidArgumentException('Permission berlainan modul.');Database::query($p,'INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)',[$id,$pid]);}Audit::record($p,'role.permissions_changed',$actor,null,(string)$id,$module,'Role definition update',$before,['permissions'=>$permissions,'name'=>$name]);return $id;});
    }
    public static function assign(\PDO $p,int $actor,int $user,int $role,?int $org,bool $desc,string $reason): void {
        $reason=Core::text($reason,500);Core::tx($p,function()use($p,$actor,$user,$role,$org,$desc,$reason){
            $r=Database::query($p,'SELECT * FROM roles WHERE id=? AND is_active=1',[$role])->fetch();$u=Database::query($p,'SELECT u.*,sp.organisation_id FROM users u JOIN staff_profiles sp ON sp.staff_identity_id=u.staff_identity_id WHERE u.id=? FOR UPDATE',[$user])->fetch();if(!$r||!$u)throw new \InvalidArgumentException('Pengguna/role tidak sah.');Authorization::require($p,$actor,'core.roles.manage',$org);Authorization::require($p,$actor,'core.users.manage',$u['organisation_id']===null?null:(int)$u['organisation_id']);
            $super=Authorization::super($p,$actor);if(!$super){if($org===null||$r['code']==='super_admin'||$user===$actor||$r['module_code']!=='core')throw new \RuntimeException('Delegasi tidak dibenarkan.');$rank=['staff'=>1,'unit_admin'=>2,'clinic_admin'=>3,'pkd_admin'=>4];$max=self::level($p,$actor,$org);if(!isset($rank[$r['code']])||$rank[$r['code']] >= $max)throw new \RuntimeException('Role melebihi kuasa delegasi.');if($desc){foreach(Database::query($p,'SELECT descendant_id FROM organisation_hierarchy WHERE ancestor_id=?',[$org])->fetchAll() as $child)Authorization::require($p,$actor,'core.roles.manage',(int)$child['descendant_id']);}}
            if($r['code']==='super_admin'&&$org!==null)throw new \InvalidArgumentException('Super Admin memerlukan scope global.');if($r['code']!=='super_admin'&&$org===null)throw new \InvalidArgumentException('Scope organisasi diperlukan.');
            if($org!==null&&!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$org])->fetchColumn())throw new \InvalidArgumentException('Organisasi tidak aktif.');
            // Require scope and organisational membership to intersect for delegated core roles.
            if(!$super&&$u['organisation_id']!==null&&!($u['organisation_id']==$org||($desc&&Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$org,$u['organisation_id']])->fetchColumn())))throw new \RuntimeException('Pengguna di luar scope assignment.');
            Database::query($p,'INSERT INTO user_role_assignments(user_id,role_id,organisation_id,include_descendants,module_code) VALUES(?,?,?,?,?)',[$user,$role,$org,$desc?1:0,$r['module_code']]);$data=['user_id'=>$user,'role_id'=>$role,'organisation_id'=>$org,'include_descendants'=>$desc,'module_code'=>$r['module_code']];self::history($p,$actor,$user,'ASSIGN',$data,$reason);Audit::record($p,'role.assigned',$actor,$org,(string)$user,$r['module_code'],$reason,null,$data);
        });
    }
    public static function revoke(\PDO $p,int $actor,int $assignment,string $reason): void {
        if((int)Database::query($p,"SELECT GET_LOCK(CONCAT('ep_accounts_',LEFT(SHA2(DATABASE(),256),40)),5)")->fetchColumn()!==1)throw new \RuntimeException('Cuba semula.');
        try{Core::tx($p,function()use($p,$actor,$assignment,$reason){$a=Database::query($p,'SELECT a.*,r.code FROM user_role_assignments a JOIN roles r ON r.id=a.role_id WHERE a.id=? FOR UPDATE',[$assignment])->fetch();if(!$a)throw new \InvalidArgumentException('Assignment tidak wujud.');$org=$a['organisation_id']===null?null:(int)$a['organisation_id'];Authorization::require($p,$actor,'core.roles.manage',$org);if(!Authorization::super($p,$actor)){$target=Database::query($p,'SELECT organisation_id FROM staff_profiles p JOIN users u ON u.staff_identity_id=p.staff_identity_id WHERE u.id=?',[$a['user_id']])->fetchColumn();Authorization::require($p,$actor,'core.users.manage',$target===null?null:(int)$target);if(!isset(self::RANK[$a['code']])||self::RANK[$a['code']]>=self::level($p,$actor,$org))throw new \RuntimeException('Pembatalan memerlukan pentadbir lebih tinggi.');}
            if($a['code']==='super_admin'&&self::activeSupers($p)<=1)throw new \RuntimeException('Super Admin terakhir mesti dikekalkan.');Database::query($p,'DELETE FROM user_role_assignments WHERE id=?',[$assignment]);self::history($p,$actor,(int)$a['user_id'],'REVOKE',$a,Core::text($reason,500));Audit::record($p,'role.revoked',$actor,$org,(string)$a['user_id'],$a['module_code'],$reason,$a,null);});}finally{Database::query($p,"SELECT RELEASE_LOCK(CONCAT('ep_accounts_',LEFT(SHA2(DATABASE(),256),40)))");}
    }
    public const RANK=['staff'=>1,'unit_admin'=>2,'clinic_admin'=>3,'pkd_admin'=>4,'super_admin'=>100];
    public static function level(\PDO $p,int $actor,?int $org):int {
        $max=0;foreach(Authorization::assignments($p,$actor,'core.roles.manage') as $a){$root=$a['organisation_id'];$applies=$root===null&&$a['code']==='super_admin'||$org!==null&&((int)$root===$org||$a['include_descendants']&&Database::query($p,'SELECT 1 FROM organisation_hierarchy WHERE ancestor_id=? AND descendant_id=?',[$root,$org])->fetchColumn());if($applies)$max=max($max,self::RANK[$a['code']]??0);}return $max;
    }
    public static function activeSupers(\PDO $p): int {return (int)$p->query("SELECT COUNT(DISTINCT a.user_id) FROM user_role_assignments a JOIN roles r ON r.id=a.role_id JOIN users u ON u.id=a.user_id WHERE r.code='super_admin' AND a.organisation_id IS NULL AND u.is_active=1")->fetchColumn();}
    private static function history(\PDO $p,int $actor,int $user,string $action,array $data,string $reason):void {Database::query($p,'INSERT INTO role_assignment_history(user_id,actor_id,action,assignment_json,reason) VALUES(?,?,?,?,?)',[$user,$actor,$action,json_encode($data,JSON_THROW_ON_ERROR),$reason]);}
}
